import os
import sys
import re
import requests
from pathlib import Path
from typing import Optional

# Constants for paths relative to project root
PROJECT_ROOT = Path(__file__).resolve().parent.parent.parent
ASSETS_DIR = PROJECT_ROOT / "assets"
TEMPLATES_DIR = ASSETS_DIR / "templates"
VERIFIED_URL_FILE = TEMPLATES_DIR / "verified_template_url.txt"
OUTPUT_FILE = TEMPLATES_DIR / "TEMPLATE-001-v1.0.md"

def read_verified_url() -> str:
    """Read the verified URL from the file generated by T009a."""
    if not VERIFIED_URL_FILE.exists():
        raise FileNotFoundError(
            f"Verified URL file not found at {VERIFIED_URL_FILE}. "
            "Ensure T009a has completed successfully."
        )
    url = VERIFIED_URL_FILE.read_text(encoding="utf-8").strip()
    if not url:
        raise ValueError("Verified URL file is empty.")
    return url

def fetch_url_content(url: str) -> str:
    """Fetch raw HTML content from the URL."""
    try:
        response = requests.get(url, timeout=30)
        response.raise_for_status()
        return response.text
    except requests.RequestException as e:
        raise RuntimeError(f"Failed to fetch URL {url}: {e}")

def clean_html_tags(html_content: str) -> str:
    """Remove all HTML tags from the content."""
    clean = re.sub(r'<.*?>', '', html_content)
    # Normalize whitespace
    clean = re.sub(r'\s+', ' ', clean).strip()
    return clean

def extract_protocol_content(html_content: str) -> str:
    """
    Extract protocol content from HTML.
    Attempts to find content within <div class="protocol"> or similar structures.
    If specific tags are not found, falls back to extracting the first substantial text block
    or cleaning the entire body if it looks like a single-page protocol.
    """
    # Try to find content within a protocol-specific div
    protocol_match = re.search(r'<div[^>]*class=["\']protocol["\'][^>]*>(.*?)</div>', html_content, re.DOTALL | re.IGNORECASE)
    if protocol_match:
        return protocol_match.group(1)

    # Try to find content within a specific section header if div not found
    # e.g., <h2>Protocol</h2> ... </h2> or similar patterns
    section_match = re.search(r'<h[1-3][^>]*>.*?Protocol.*?</h[1-3]>(.*?)<(h[1-3]|div|body)', html_content, re.DOTALL | re.IGNORECASE)
    if section_match:
        return section_match.group(1)

    # Fallback: If the page seems to be just the protocol, return the body content
    body_match = re.search(r'<body[^>]*>(.*?)</body>', html_content, re.DOTALL | re.IGNORECASE)
    if body_match:
        return body_match.group(1)

    # Last resort: return the whole content (will be cleaned later)
    return html_content

def save_protocol_content(content: str, output_path: Path) -> None:
    """Save the extracted and cleaned content to the output file."""
    # Ensure directory exists
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(content, encoding="utf-8")

def main():
    """Main entry point for fetching and normalizing the template."""
    try:
        # 1. Read the verified URL
        url = read_verified_url()
        print(f"Fetching template from: {url}")

        # 2. Fetch the content
        raw_html = fetch_url_content(url)

        # 3. Extract protocol content
        raw_protocol = extract_protocol_content(raw_html)

        # 4. Clean HTML tags
        clean_text = clean_html_tags(raw_protocol)

        # 5. Save to the specified output file
        save_protocol_content(clean_text, OUTPUT_FILE)
        print(f"Template saved successfully to: {OUTPUT_FILE}")

    except FileNotFoundError as e:
        print(f"ERROR: {e}", file=sys.stderr)
        sys.exit(1)
    except RuntimeError as e:
        print(f"ERROR: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"UNEXPECTED ERROR: {e}", file=sys.stderr)
        sys.exit(1)
